            case 'regex': {
                if ($value === '') return false;
                // Защита от ReDoS: ограничиваем backtrack limit
                $prevLimit = ini_get('pcre.backtrack_limit');
                if ((int)$prevLimit > 1000000) {
                    ini_set('pcre.backtrack_limit', '1000000');
                }
                $result = @preg_match($value, $subject);
                if ((int)$prevLimit > 1000000) {
                    ini_set('pcre.backtrack_limit', $prevLimit);
                }
                return $result !== false && (bool)$result;
            }
            case 'not_regex': {
                if ($value === '') return true;
                $prevLimit = ini_get('pcre.backtrack_limit');
                if ((int)$prevLimit > 1000000) {
                    ini_set('pcre.backtrack_limit', '1000000');
                }
                $result = @preg_match($value, $subject);
                if ((int)$prevLimit > 1000000) {
                    ini_set('pcre.backtrack_limit', $prevLimit);
                }
                return $result === false || !(bool)$result;
            }

